<?php
if(getenv('UMMAH_REVIEW_ENVIRONMENT')!=='isolated-staging'||getenv('UMMAH_NATIVE_FIXTURE')!=='sandbox-only')throw new RuntimeException('Sandbox qualification only.');
$root=realpath(getenv('HUMHUB_ROOT')?:'');$file=getenv('UMMAH_NATIVE_FIXTURE_FILE');
if(!$root||!$file||(fileperms($file)&0077))throw new RuntimeException('Protected fixture required.');
$f=json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);
if(($f['kind']??'')!=='native-humhub-sandbox-fixture')throw new RuntimeException('Not a native fixture.');
$_SERVER['SCRIPT_FILENAME']=$root.'/index.php';$_SERVER['SCRIPT_NAME']='/index.php';$_SERVER['HTTP_HOST']='127.0.0.1:3401';$_SERVER['REQUEST_URI']='/';
define('YII_DEBUG',false);define('YII_ENV','prod');require $root.'/protected/vendor/autoload.php';require $root.'/protected/vendor/yiisoft/yii2/Yii.php';Yii::setAlias('@humhub',$root.'/protected/humhub');
$bootstrap=new humhub\services\BootstrapService();$config=$bootstrap->getConfig('web');$config['components']['user']['enableSession']=false;$app=new humhub\components\Application($config);
use humhub\modules\user\models\User;
use humhub\modules\space\models\Space;
use humhub\modules\post\models\Post;
use humhub\modules\content\models\Content;
use humhub\modules\ummahreview\Events;
use yii\base\Event;
$app->user->switchIdentity(User::findOne($f['accounts']['author']['id']));$space=Space::findOne($f['spaceId']);$results=[];
function checkNative($name,$fn){global $results;try{$fn();$results[]=['name'=>$name,'status'=>'pass'];echo 'PASS '.$name."\n";}catch(Throwable $e){$results[]=['name'=>$name,'status'=>'fail','error'=>substr($e->getMessage(),0,300)];echo 'FAIL '.$name.' '.substr($e->getMessage(),0,300)."\n";}}
function must($ok,$message){if(!$ok)throw new RuntimeException($message);}
$post=null;$firstStates=[];
Event::on(Content::class,Content::EVENT_AFTER_INSERT,function($event)use(&$firstStates){$c=$event->sender;if($c->object_model===Post::class)$firstStates[]=(int)$c->state;});
checkNative('Native create without reviewed-submit context is denied without orphan Post',function()use($space){$p=new Post($space,['message'=>'Denied raw native create, synthetic qualification.']);$p->content->state=Content::STATE_PUBLISHED;must(!$p->save(),'Raw create unexpectedly succeeded');must($p->isNewRecord,'Orphan native Post inserted');});
checkNative('Guarded submission first Content INSERT is draft, never briefly published',function()use($space,&$post,&$firstStates){$post=new Post($space,['message'=>'Native bypass fixture, not genuine scholarship.','title'=>'Native guard qualification']);$post->content->state=Content::STATE_PUBLISHED;$post->content->visibility=Content::VISIBILITY_PUBLIC;must(Events::saveSubmittedDraft($post),'Guarded save rejected');must($firstStates===[Content::STATE_DRAFT],'Observed non-draft first insert');must((int)$post->content->state===Content::STATE_DRAFT,'Final state is not draft');must((int)$post->content->visibility===Content::VISIBILITY_PRIVATE,'Content became public');});
checkNative('Unreviewed native state-service publishing blocked',function()use(&$post){must($post,'Missing post');must(!$post->content->getStateService()->publish(),'Unreviewed publication succeeded');$post->content->refresh();must((int)$post->content->state===Content::STATE_DRAFT,'Unreviewed state changed');});
checkNative('Unreviewed scheduled publication blocked',function()use(&$post){$post->content->state=Content::STATE_SCHEDULED;$post->content->scheduled_at='2099-01-01 00:00:00';must(!$post->content->save(false),'Scheduling bypass succeeded');$post->content->refresh();must((int)$post->content->state===Content::STATE_DRAFT,'Draft lost');});
checkNative('Approved message cannot mutate through native Post::save',function()use($app){$row=$app->db->createCommand("SELECT post_id FROM ummah_review WHERE status='approved' ORDER BY id DESC LIMIT 1")->queryOne();must($row,'No approved fixture');$p=Post::findOne($row['post_id']);$before=$p->message;$p->message='Unauthorized altered scholarly claim';must(!$p->save(false),'Approved mutation succeeded');$p->refresh();must($p->message===$before,'Approved content changed');});
checkNative('Rejected post cannot publish through native state service',function()use($app){$row=$app->db->createCommand("SELECT post_id FROM ummah_review WHERE status='rejected' ORDER BY id DESC LIMIT 1")->queryOne();must($row,'No rejected fixture');$p=Post::findOne($row['post_id']);must(!$p->content->getStateService()->publish(),'Rejected native publication succeeded');$p->content->refresh();must((int)$p->content->state===Content::STATE_DRAFT,'Rejected content left draft');});
checkNative('Native force move cannot transfer an approved post or its review binding',function()use($app,$f){$row=$app->db->createCommand("SELECT post_id FROM ummah_review WHERE status='approved' ORDER BY id DESC LIMIT 1")->queryOne();$p=Post::findOne($row['post_id']);$before=$p->content->contentcontainer_id;must(!$p->content->move(Space::findOne($f['forbiddenSpaceId']),true),'Force move succeeded');$p->content->refresh();must((int)$p->content->contentcontainer_id===(int)$before,'Container changed');});
checkNative('Raw native updateAttributes cannot make approved content public',function()use($app){$row=$app->db->createCommand("SELECT post_id FROM ummah_review WHERE status='approved' ORDER BY id DESC LIMIT 1")->queryOne();$p=Post::findOne($row['post_id']);must($p->content->updateAttributes(['visibility'=>Content::VISIBILITY_PUBLIC])===0,'Raw visibility write succeeded');$p->content->refresh();must((int)$p->content->visibility===Content::VISIBILITY_PRIVATE,'Content became public');});
checkNative('Pending and rejected detail denied even to owner or native content manager',function()use($app,$f){foreach(['pending','rejected']as$status){$row=$app->db->createCommand('SELECT post_id FROM ummah_review WHERE status=:s ORDER BY id DESC LIMIT 1',[':s'=>$status])->queryOne();$p=Post::findOne($row['post_id']);must(!$p->content->canView(User::findOne($f['accounts']['author']['id'])),'Author native detail leaked');must(!$p->content->canView(User::findOne($f['accounts']['reviewer']['id'])),'Reviewer raw detail leaked');}});
checkNative('Native readable search/feed query excludes pending and rejected posts',function()use($app,$space){$ids=$app->db->createCommand("SELECT post_id FROM ummah_review WHERE status IN ('pending','rejected')")->queryColumn();$visible=Post::find()->contentContainer($space)->readable()->all();foreach($visible as$p)must(!in_array((string)$p->id,array_map('strval',$ids),true),'Native readable query leaked a draft');});
checkNative('Native approved detail denies excluded community user',function()use($app,$f){$row=$app->db->createCommand("SELECT post_id FROM ummah_review WHERE status='approved' ORDER BY id DESC LIMIT 1")->queryOne();$p=Post::findOne($row['post_id']);must(!$p->content->canView(User::findOne($f['accounts']['excluded']['id'])),'Excluded native detail allowed');});
checkNative('Unlinked native file remains writable and owner-readable',function()use(&$fixtureFile){$fixtureFile=new humhub\modules\file\models\File(['guid'=>humhub\libs\UUID::v4(),'file_name'=>'native-guard-fixture.txt','mime_type'=>'text/plain','size'=>0,'public'=>0]);must($fixtureFile->save(false),'Unrelated native file blocked');must($fixtureFile->canView(),'Owner cannot read unrelated file');});
checkNative('Native File save and raw assignment cannot attach to a reviewed post',function()use($app,&$fixtureFile){must($fixtureFile,'Missing synthetic file');$row=$app->db->createCommand("SELECT post_id FROM ummah_review WHERE status='approved' ORDER BY id DESC LIMIT 1")->queryOne();foreach(['save','raw']as$method){$denied=false;try{if($method==='save'){$fixtureFile->object_model=Post::getObjectModel();$fixtureFile->object_id=$row['post_id'];$fixtureFile->save(false);}else{$fixtureFile->updateAttributes(['object_model'=>Post::getObjectModel(),'object_id'=>$row['post_id']]);}}catch(yii\web\ForbiddenHttpException){$denied=true;}must($denied,'File assignment bypass succeeded');$fixtureFile->refresh();must(empty($fixtureFile->object_model),'File linkage persisted');}});
checkNative('Unexpected public attachment denies file view, replacement and deletion before side effects',function()use($app,$f,&$fixtureFile){must($fixtureFile,'Missing synthetic file');$row=$app->db->createCommand("SELECT post_id FROM ummah_review WHERE status='approved' ORDER BY id DESC LIMIT 1")->queryOne();$app->db->createCommand()->update('file',['object_model'=>Post::getObjectModel(),'object_id'=>$row['post_id'],'public'=>1],['id'=>$fixtureFile->id])->execute();try{$fixtureFile->refresh();foreach(['author','reviewer','excluded']as$role)must(!$fixtureFile->canView(User::findOne($f['accounts'][$role]['id'])),'Public/owner File shortcut leaked');$post=Post::findOne($row['post_id']);must(!$post->content->canView(),'Unexpected attachment retained approval visibility');foreach(['delete','replace']as$operation){$denied=false;try{if($operation==='delete')$fixtureFile->delete();else{$fixtureFile->file_name='replacement-fixture.txt';$fixtureFile->save(false);}}catch(yii\web\ForbiddenHttpException){$denied=true;}must($denied,'Linked file mutation succeeded');}must(humhub\modules\file\models\File::findOne($fixtureFile->id),'File destroyed despite denial');}finally{$app->db->createCommand()->update('file',['object_model'=>null,'object_id'=>null,'public'=>0],['id'=>$fixtureFile->id])->execute();$fixtureFile->refresh();}});
checkNative('Real cached search rechecks membership and excludes pending/rejected content',function()use($app,$f){$driver=$app->getModule('content')->getSearchDriver();$rows=$app->db->createCommand("SELECT content_id,status FROM ummah_review WHERE space_id=:id ORDER BY id DESC LIMIT 40",[':id'=>$f['spaceId']])->queryAll();foreach($rows as$row)$driver->update(Content::findOne($row['content_id']));$request=new humhub\modules\content\search\SearchRequest(['keyword'=>'Native','pageSize'=>100]);$first=$driver->searchCached($request,2);$approved=$app->db->createCommand("SELECT content_id FROM ummah_review WHERE status='approved'")->queryColumn();$allowed=false;foreach($first->results as$content){if($content->object_model===Post::getObjectModel()){must(in_array((string)$content->id,array_map('strval',$approved),true),'Search exposed draft/rejected');$allowed=true;}}must($allowed,'Vacuous cache test: no actual approved result');$where=['space_id'=>$f['spaceId'],'user_id'=>$f['accounts']['author']['id']];$app->db->createCommand()->update('space_membership',['status'=>0],$where)->execute();try{$cached=$driver->searchCached(new humhub\modules\content\search\SearchRequest(['keyword'=>'Native','pageSize'=>100]),2);foreach($cached->results as$content)must($content->object_model!==Post::getObjectModel(),'Cached private Post leaked after membership revoked');}finally{$app->db->createCommand()->update('space_membership',['status'=>3],$where)->execute();}});
$report=['kind'=>'actual-humhub-native-model-guards','transport'=>getenv('UMMAH_NATIVE_DB_DESCRIPTION')?:'native Yii models with real MariaDB','results'=>$results,'passed'=>count(array_filter($results,fn($r)=>$r['status']==='pass')),'failed'=>count(array_filter($results,fn($r)=>$r['status']==='fail')),'humanParticipation'=>false,'physicalIPhoneSafariTested'=>false];
if(getenv('UMMAH_NATIVE_MODEL_REPORT_FILE'))file_put_contents(getenv('UMMAH_NATIVE_MODEL_REPORT_FILE'),json_encode($report,JSON_PRETTY_PRINT)."\n");echo json_encode(['passed'=>$report['passed'],'failed'=>$report['failed']]),"\n";exit($report['failed']?1:0);
